-- ============================================================================
-- v131: 语文[职高] 应用文写作L4知识点扩充
-- 对齐2024年四川省对口升学考试大纲（小作文部分）
-- 新增6种文体：便条、单据、计划、说明书、求职信、应聘书
-- ============================================================================

SET @app_writing_id = 862;  -- 应用文写作(L3)
SET @subject_id = 20;

-- ============================================================
-- 创建6个新L4节点（INSERT IGNORE幂等）
-- ============================================================
INSERT IGNORE INTO knowledge_nodes (parent_id, subject_id, level, name, sort_order, created_at, updated_at)
VALUES
(@app_writing_id, @subject_id, 4, '便条', 7, NOW(), NOW()),
(@app_writing_id, @subject_id, 4, '单据', 8, NOW(), NOW()),
(@app_writing_id, @subject_id, 4, '计划', 9, NOW(), NOW()),
(@app_writing_id, @subject_id, 4, '说明书', 10, NOW(), NOW()),
(@app_writing_id, @subject_id, 4, '求职信', 11, NOW(), NOW()),
(@app_writing_id, @subject_id, 4, '应聘书', 12, NOW(), NOW());

-- ============================================================
-- 填充6个新L4节点的教学内容（【定义】→【具体说明】→【常见错误】→【考试方向】）
-- ============================================================

UPDATE knowledge_nodes SET content =
'【一句话定义】\n便条是一种简易的书信式应用文，用于向他人说明事项、提出请求或表达歉意，格式比书信更简化，适用于非正式的日常场合。\n\n【具体说明】\n① 常见类型：请假条（向老师/领导请假·核心同条据中的请假条）、留言条（找人不在时留言·交代事由和联系人）、托事条（托人办事·说明事项和联系方式）、致歉条（表达歉意·说明原因和态度）。\n② 格式要素：称呼（顶格）+正文（空两格·简明交代事项）+敬语（"此致 敬礼"可简化为"谢谢"或"祝好"）+署名+日期。\n③ 与条据的区别：条据侧重凭证功能（借条/收条/请假条·有法律效力），便条侧重沟通功能（留言/托事/致歉·无凭证效力）。\n④ 语言要求：简洁明了、语气亲切自然、交代清楚5W（who/what/when/where/why）。\n\n【常见错误】\n1. 便条缺少联系方式→找人不在留便条不写电话号码，对方无法联系\n2. 语气不当→托人办事语气生硬（"你去帮我拿快递"→"麻烦帮我取一下快递，谢谢"）\n3. 事项交代不清楚→"明天老地方见"没写明具体时间和地点\n\n【考试方向】\n根据情境写便条：如"你去同学家送书但同学不在，写一张便条"。'
WHERE parent_id = @app_writing_id AND name = '便条';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n单据是记录经济往来、具有凭证作用的条据类应用文，包括借条、收条、领条、欠条等，要求内容准确、格式规范、无歧义。\n\n【具体说明】\n① 常见类型：借条（借入钱物·写明金额大写/物品数量·归还日期）、收条（收到钱物·写明来源/金额/用途）、领条（领用物品·写明领用人和物品清单）、欠条（欠人钱物·写明欠款原因和还款计划）。\n② 格式要素：标题居中（"借条""收条"等）+正文（"今借到""今收到""今领到""今欠"等开头）+金额大写（壹贰叁肆伍陆柒捌玖拾佰仟萬·元角分）+物品清单（名称/数量/规格）+签名（借款人/收款人签名）+日期（年/月/日）。\n③ 书写规范：金额必须大写（防止篡改）·"10,000元"应写为"人民币壹万元整"；不写阿拉伯数字只写大写数字；不留空白（正文与签名间不留空行·防止擅自添加内容）。\n④ 与便条区别：单据有法律凭证功能（形成债务/债权关系），便条无凭证功能仅用于沟通。\n\n【常见错误】\n1. 金额不用大写→阿拉伯数字易篡改·"借10000元"可改成"借100000元"\n2. 不写归还日期→"今借到张三名下人民币伍仟元整"缺归还日期\n3. 署名不规范→只写名不写姓或写成别名·应写完整姓名并按手印/盖章\n\n【考试方向】\n根据情境写单据：如"你向同学借了200元买书，请写一张借条"。'
WHERE parent_id = @app_writing_id AND name = '单据';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n计划是对未来一段时间内的工作、学习或活动做出的预先安排和规划，是一种具有前瞻性和指导性的应用文体。\n\n【具体说明】\n① 常见类型：学习计划（学习目标/时间安排/复习进度）、工作计划（工作目标/任务分解/时间节点）、活动计划（活动方案/人员分工/流程安排）。\n② 结构要素：标题（"XX计划"居中）+前言（制定计划的目的/背景/依据·简洁概述）+目标（要达到的具体目标·量化可考核）+内容与步骤（做什么·怎么做·分几个阶段·每阶段具体任务）+时间安排（起止时间/各阶段时间节点）+保障措施（人员和资源保障/可能出现的问题及对策）+署名+日期。\n③ 语言要求：条理清晰（分条列项·用序号标注）、目标明确（可量化可考核·"每天背20个单词"而非"提高英语水平"）、措施具体（可操作·"每天早上6点起床读书"而非"早睡早起"）、时间合理（留有余地·不排得太满）。\n④ 与总结关系：计划是"事前规划"（做什么），总结是"事后回顾"（做得怎样）。\n\n【常见错误】\n1. 目标太笼统→"努力学习""好好工作"不能考核\n2. 没有时间节点→"本学期要多读书"无时间安排等于空话\n3. 不分条罗列→写成抒情散文而非分条说明的计划\n\n【考试方向】\n根据情境制定计划：如"期末考试将至，请你制定一份期末复习计划"。'
WHERE parent_id = @app_writing_id AND name = '计划';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n说明书是以说明为主要表达方式，向读者介绍产品用途、使用方法、注意事项或活动规则的实用性应用文体。\n\n【具体说明】\n① 常见类型：产品说明书（介绍产品功能/使用方法/注意事项/保养维护）、活动说明书/须知（说明活动规则/参与方式/时间地点/注意事项）、操作规程（介绍操作步骤和安全要求）。\n② 结构要素：标题（"XX说明书"或"XX使用说明"+品名+型号）+正文（产品概述/主要功能/技术参数·分条列项）+使用方法（操作步骤·按顺序编号·每步一句·可附图说明）+注意事项（安全警告/禁忌/保修说明）+制造商信息。\n③ 语言要求：准确科学（不含糊·"连续使用不超过30分钟"非"不要用太久"）、条理清晰（按使用顺序编排·用序号标注）、通俗易懂（目标读者是普通用户·避免专业术语）、简明扼要（不啰嗦·用短句）。\n④ 常见说明方法：列数字（功率200W/重量1.5kg）、分类别（按功能分为三大类）、作比较（与上一代产品对比）、下定义（说明产品类别）。\n\n【常见错误】\n1. 语言含糊→"适量加入"不如"加入5-10克"\n2. 缺少安全提示→电器未说明"请勿在潮湿环境使用"\n3. 顺序混乱→未按操作自然顺序写·用户看了无法跟着操作\n\n【考试方向】\n根据情境写说明：如"请你为学校新购买的饮水机写一份使用说明书"或"为校园文化艺术节写一份活动须知"。'
WHERE parent_id = @app_writing_id AND name = '说明书';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n求职信是求职者向用人单位介绍自己、表达求职意愿的书信体应用文，目的是争取面试机会。\n\n【具体说明】\n① 格式要素：称呼（顶格·"尊敬的XX公司领导"或"尊敬的招聘负责人"）+问候语（"您好"）+正文（求职意向+自我介绍+能力展示+求职意愿）+祝颂语（"此致 敬礼"·此致空两格/敬礼顶格）+署名+日期+联系方式（电话/邮箱/地址）。\n② 正文四段式：第一段-表明求职意向和消息来源（"从XX招聘网获悉贵公司正在招聘XX岗位，特写信应聘"）；第二段-自我介绍和能力展示（学历/专业/技能/实习经历/获奖·针对岗位要求写·用事实和数据说话）；第三段-表达诚意和态度（"我热爱XX工作，愿意从基层做起，虚心学习"）；第四段-请求面试并附联系方式（"恳请给予面试机会，期待您的回音"）。\n③ 语言要求：礼貌得体（用"贵公司""恳请""感谢"等敬辞）、自信但不自夸（"我具备XX能力"有依据非"我非常厉害"）、简洁清晰（一页纸为宜·不啰嗦）、真诚朴实（不以华丽辞藻掩盖空洞内容）。\n④ 与应聘书区别：求职信是主动询问是否有岗位（你还不知道招不招），应聘书是回应具体招聘的申请书（对方已明确招聘）。\n\n【常见错误】\n1. 千篇一律无针对性→同一封求职信群发·没针对岗位修改\n2. 空话多实据少→"我工作能力强"不如"我在校期间担任班长，组织过3次大型活动"\n3. 格式错误→漏写联系方式·漏写日期\n\n【考试方向】\n根据招聘信息写求职信：题干提供公司信息和岗位需求，要求写一封求职信。'
WHERE parent_id = @app_writing_id AND name = '求职信';

UPDATE knowledge_nodes SET content =
'【一句话定义】\n应聘书是应聘者针对用人单位发布的招聘信息，正式表达应聘意愿并介绍自己相关条件的一种书信体应用文。\n\n【具体说明】\n① 格式要素：称呼（顶格·"尊敬的XX公司领导"）+问候语+正文（表明应聘意愿/对照岗位要求阐述自身优势/表达加入意愿）+祝颂语+署名+日期+联系方式。\n② 正文结构：第一段-表明应聘意愿（"欣闻贵公司招聘XX岗位，本人对照招聘要求，认为自己符合条件，特写信应聘"）；第二段-逐一回应岗位要求（"贵公司要求应聘者具备以下条件：①XX能力——我曾在XX项目中担任XX；②XX证书——我已取得XX证书……"·一一对应逐一说明）；第三段-表达态度和承诺（"如能加入贵公司，我必将努力工作，不断提升自己"）；第四段-礼貌结尾（"恳请审阅我的材料，期待您的面试通知"）。\n③ 与求职信区别：求职信是广谱投递（"请问你们需要人吗"），应聘书是精准回应（"我符合你们的要求，我来应聘"）。应聘书更强调"对照要求"——把自己的条件与招聘要求逐条对应。\n④ 语言要求：对应性强（招聘要求有什么我就说什么）、实事求是（不虚构不夸大）、语气自信诚恳（"我相信我能胜任"优于"我觉得我可能行"）。\n\n【常见错误】\n1. 不回应具体岗位要求→招聘要求写了5条·应聘书只泛泛介绍自己\n2. 语气不当→"如果你们录用我"太被动·改为"恳请给予面谈机会"\n3. 与求职信写法混淆→应聘书要针对具体招聘·不是通用的自我介绍\n\n【考试方向】\n根据招聘启事写应聘书：题干提供招聘信息，要求写一封应聘书。'
WHERE parent_id = @app_writing_id AND name = '应聘书';

SELECT 'v131: 应用文写作6个新L4节点 + 内容填充完成！' AS result;
SELECT CONCAT('应用文写作下共 ', COUNT(*), ' 个知识点（原6+新6=12）') FROM knowledge_nodes WHERE parent_id = @app_writing_id;
